  ('dapagliflozina', 'Dapagliflozina', 'Dapagliflozin', 'Inibidor do cotransportador sódio-glicose 2 (SGLT2)', 'Sodium-glucose cotransporter 2 (SGLT2) inhibitor', ARRAY['Farxiga', 'Forxiga'], 'published', 143),
  ('canagliflozina', 'Canagliflozina', 'Canagliflozin', 'Inibidor do cotransportador sódio-glicose 2 (SGLT2)', 'Sodium-glucose cotransporter 2 (SGLT2) inhibitor', ARRAY['Invokana'], 'published', 144),
  ('sitagliptina', 'Sitagliptina', 'Sitagliptin', 'Inibidor da dipeptidil peptidase-4 (DPP-4)', 'Dipeptidyl peptidase-4 (DPP-4) inhibitor', ARRAY['Januvia'], 'published', 145),
  ('saxagliptina', 'Saxagliptina', 'Saxagliptin', 'Inibidor da dipeptidil peptidase-4 (DPP-4)', 'Dipeptidyl peptidase-4 (DPP-4) inhibitor', ARRAY['Onglyza'], 'published', 146),
  ('vildagliptina', 'Vildagliptina', 'Vildagliptin', 'Inibidor da dipeptidil peptidase-4 (DPP-4)', 'Dipeptidyl peptidase-4 (DPP-4) inhibitor', ARRAY['Galvus'], 'published', 147),
  ('liraglutida', 'Liraglutida', 'Liraglutide', 'Agonista do recetor do peptídeo semelhante ao glucagon-1 (GLP-1 RA)', 'Glucagon-like peptide-1 receptor agonist (GLP-1 RA)', ARRAY['Victoza', 'Saxenda'], 'published', 148),
  ('dulaglutida', 'Dulaglutida', 'Dulaglutide', 'Agonista do recetor do peptídeo semelhante ao glucagon-1 (GLP-1 RA)', 'Glucagon-like peptide-1 receptor agonist (GLP-1 RA)', ARRAY['Trulicity'], 'published', 149),
