-- =====================================================================
-- 3. Farmacologia (drug_pharmacology)
-- =====================================================================
INSERT INTO public.drug_pharmacology
  (drug_id, pharmacodynamics_pt, pharmacodynamics_en,
   mechanism_pt, mechanism_en,
   metabolism_pt, metabolism_en,
   absorption_pt, absorption_en,
   half_life_pt, half_life_en,
   source_pt, source_en, status)
SELECT d.id,
  v.pharmacodynamics_pt, v.pharmacodynamics_en,
  v.mechanism_pt, v.mechanism_en,
  v.metabolism_pt, v.metabolism_en,
  v.absorption_pt, v.absorption_en,
  v.half_life_pt, v.half_life_en,
  v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('empagliflozina',
   'Inibe seletivamente o SGLT2 no túbulo contorcido proximal, bloqueando 80-90% da reabsorção de glicose renal.',
   'Selectively inhibits SGLT2 in the proximal convoluted tubule, blocking 80-90% of renal glucose reabsorption.',
   'Bloqueia o SGLT2, impedindo o transporte de glicose de volta para a circulação. A glicose é excretada na urina (glicosúria ~70 g/dia).',
   'Blocks SGLT2, preventing glucose transport back into circulation. Glucose is excreted in urine (~70 g/day glycosuria).',
   'Metabolizado por UGT1A3, UGT1A8, UGT1A9 ao glucurónido inativo. Não interfere com CYP. Baixo potencial de interações.',
   'Metabolised by UGT1A3, UGT1A8, UGT1A9 to inactive glucuronide. Does not interfere with CYP. Low interaction potential.',
   'Biodisponibilidade oral: 78%. Alimentos não afetam significativamente a absorção. Tmax: 1,5 horas.',
   'Oral bioavailability: 78%. Food does not significantly affect absorption. Tmax: 1.5 hours.',
   '12,4 horas. Eliminação: 54% fezes, 36% urina (metabolitos).',
   '12.4 hours. Elimination: 54% faeces, 36% urine (metabolites).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Empagliflozina (Jardiance): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8b6261f6-4bdc-462e-8af1-4064664c62f3',
   'DailyMed/FDA (NIH/NLM) — approved Empagliflozin (Jardiance) label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8b6261f6-4bdc-462e-8af1-4064664c62f3'),
  ('dapagliflozina',
   'Inibe seletivamente o SGLT2, bloqueando a reabsorção renal de glicose e promovendo glicosúria.',
   'Selectively inhibits SGLT2, blocking renal glucose reabsorption and promoting glycosuria.',
   'Bloqueia o SGLT2 no túbulo proximal, impedindo o transporte de glicose. A glicose excretada arrasta sódio e água (diurético osmótico).',
   'Blocks SGLT2 in the proximal tubule, preventing glucose transport. Excreted glucose drags sodium and water (osmotic diuretic).',
   'Metabolizado por UGT1A6, UGT1A9 ao glucurónido inativo (metabolito M2). Metabolito M3 (4-hidroxil) com atividade reduzida. Não interfere com CYP.',
   'Metabolised by UGT1A6, UGT1A9 to inactive glucuronide (M2 metabolite). M3 metabolite (4-hydroxyl) with reduced activity. Does not interfere with CYP.',
   'Biodisponibilidade oral: 78%. Alimentos não afetam a absorção. Tmax: 1-2 horas.',
   'Oral bioavailability: 78%. Food does not affect absorption. Tmax: 1-2 hours.',
   '12,9 horas. Eliminação: ~75% urina (metabolitos), ~20% fezes.',
   '12.9 hours. Elimination: ~75% urine (metabolites), ~20% faeces.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Dapagliflozina (Farxiga): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=72ad22ae-efe6-4cd6-a302-98aaee423d69',
   'DailyMed/FDA (NIH/NLM) — approved Dapagliflozin (Farxiga) label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=72ad22ae-efe6-4cd6-a302-98aaee423d69'),
  ('canagliflozina',
   'Inibe o SGLT2 (seletivo) e, em menor grau, o SGLT1 (não seletivo), bloqueando a reabsorção renal de glicose.',
   'Inhibits SGLT2 (selective) and, to a lesser extent, SGLT1 (non-selective), blocking renal glucose reabsorption.',
   'Bloqueia o SGLT2 e SGLT1. A inibição do SGLT1 no intestino pode contribuir para efeitos gastrointestinais.',
   'Blocks SGLT2 and SGLT1. SGLT1 inhibition in the intestine may contribute to gastrointestinal effects.',
